    /// Indexed by Names::displayLanguageIndex(); see Names/NameLanguage.h.
    static const char* const* const MOVE_NAMES_BY_LANGUAGE[] = {
        MOVE_NAMES_JA,
        MOVE_NAMES_EN,
        MOVE_NAMES_FR,
        MOVE_NAMES_IT,
        MOVE_NAMES_DE,
        MOVE_NAMES_ES,
        MOVE_NAMES_KO,
        MOVE_NAMES_ZH_HANS,
        MOVE_NAMES_ZH_HANT,
    };
    static_assert(sizeof(MOVE_NAMES_BY_LANGUAGE) / sizeof(MOVE_NAMES_BY_LANGUAGE[0]) == LANGUAGE_COUNT, "MOVE_NAMES_BY_LANGUAGE must carry one table per language");

    const char* getMoveName(uint16_t moveId) {
        constexpr unsigned count = sizeof(MOVE_NAMES_EN) / sizeof(MOVE_NAMES_EN[0]);
        if (moveId >= count) return "-";
        return MOVE_NAMES_BY_LANGUAGE[displayLanguageIndex()][moveId];
    }

    unsigned getMoveCount() { return sizeof(MOVE_NAMES_EN) / sizeof(MOVE_NAMES_EN[0]); }
